    LANG_GERMAN_ID     = 0x07,
    LANG_SPANISH_ID    = 0x0A,
    LANG_FRENCH_ID     = 0x0C,
    LANG_ITALIAN_ID    = 0x10,
    LANG_PORTUGUESE_ID = 0x16
};

unsigned short GetThousandsSeparator()
{
    switch (GetSystemDefaultLangID() & 0x3FF) {
    case LANG_FRENCH_ID:
        return 0x0020;
    case LANG_GERMAN_ID:
    case LANG_SPANISH_ID:
    case LANG_ITALIAN_ID:
    case LANG_PORTUGUESE_ID:
        return 0x002E;
    default:
        return 0x002C;
    }
}

